  c->datos[c->fin] = x;
  c->fin = c->fin + 1;
}

int desencolar(TCola *c) {
  int x;

  x = c->datos[c->inicio];
  c->inicio = c->inicio + 1;
  return x;
}

int primero(TCola c) {
  return c.datos[c.inicio];
}

TBool vacia(TCola c) {
  if (c.inicio == c.fin) {
    return VERDADERO;
  }
  return FALSO;
}

